{
  "correction_rules": [
    "Reduce forecast overshoots following sharp upward spikes in sentiment (e.g., sentiment > 0.33) by 10-15% to avoid overreaction.",
    "Adjust downward forecasts when sentiment is consistently negative (e.g., sentiment < 0.00) by adding 5-10% to prevent premature bottoming.",
    "Apply mean reversion bias: if forecast deviates > 10% from 30-day moving average, correct toward historical mean over last 10 days.",
    "Lag correction: if true outcome is lower than forecast, reduce next forecast by 5-8% to account for delayed market reaction.",
    "Increase forecast sensitivity to recent sentiment shifts: if sentiment changes from 0.00 to 0.33 within 3 days, adjust forecast upward by 3-5%.",
    "Avoid overfitting to recent highs: if last 5 days show rising prices, cap forecast increase to 5% to prevent momentum-driven overestimation."
  ]
}
